package com.volna.profile_service.security;import io.jsonwebtoken.Claims;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.*;@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{private final JwtTokenProvider p;public JwtAuthenticationFilter(JwtTokenProvider p){this.p=p;}protected void doFilterInternal(HttpServletRequest q,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=q.getHeader("Authorization");if(h==null||!h.startsWith("Bearer ")){c.doFilter(q,s);return;}String t=h.substring(7);if(p.valid(t))try{Claims cl=p.claims(t);UUID id=p.userId(t);List<String> rs=cl.get("roles",List.class);var auth=rs==null?Collections.<SimpleGrantedAuthority>emptyList():rs.stream().map(x->new SimpleGrantedAuthority("ROLE_"+x)).toList();var pr=new AuthenticatedUser(id,rs!=null&&!rs.isEmpty()?rs.get(0):"USER");SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(pr,null,auth));}catch(Exception e){SecurityContextHolder.clearContext();}c.doFilter(q,s);}}
